WITH recent_payments AS (SELECT * FROM payments WHERE status NOT IN ('SUCCESS', 'FAILED', 'REFUNDED') AND amount >= 1110), amount_bucket_summary AS (SELECT CASE WHEN amount >= 1590 THEN 'high' WHEN amount >= 610 THEN 'mid' ELSE 'low' END AS amount_bucket, COUNT(CASE WHEN status = 'FAILED' THEN 1 END) AS failed_count FROM recent_payments GROUP BY CASE WHEN amount >= 1590 THEN 'high' WHEN amount >= 610 THEN 'mid' ELSE 'low' END) SELECT * FROM amount_bucket_summary ORDER BY amount_bucket DESC
